/**
 * Does a beginner get told something they can act on?
 *
 *   node scripts/error-messages-test.js      (from server/, needs Python)
 *
 * Every case here is generated by RUNNING code that makes the mistake, not by
 * pasting a traceback string. A hand-written fixture would keep passing after
 * Python changed its wording, which is exactly when these messages would start
 * being wrong.
 *
 * Two things are checked for each: that the right rule matched, and that the
 * line number points at the line the learner wrote.
 */
const { runPythonScript } = require('../pythonRunner');
const { explainPythonError } = require('../pythonErrorMessages');

let pass = 0, fail = 0;
const check = (ok, label, detail) => {
    console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}${detail ? '  — ' + detail : ''}`);
    ok ? pass++ : fail++;
};

// code, the kind expected, and the line the learner would point at.
const CASES = [
    ['ตัวแปรที่ยังไม่ได้สร้าง', 'a = 1\nprint(undefined_name)', 'NameError', 2, 'undefined_name'],
    ['ลืมใส่ :', 'if True\n    print(1)', 'SyntaxError', 1, ':'],
    ['ย่อหน้าไม่ถูก', 'def f():\nprint(1)', 'IndentationError', 2, 'ย่อหน้า'],
    ['วงเล็บไม่ปิด', 'print("hi"', 'SyntaxError', 1, 'วงเล็บ'],
    ['ข้อความบวกตัวเลข', 'print("a" + 1)', 'TypeError', 1, 'str()'],
    ['หารด้วยศูนย์', 'print(1 / 0)', 'ZeroDivisionError', 1, 'ศูนย์'],
    ['เรียกลิสต์เกิน', 'a = [1]\nprint(a[5])', 'IndexError', 2, '0'],
    ['แปลงข้อความเป็นเลขไม่ได้', 'int("abc")', 'ValueError', 1, 'int()'],
    ['เรียกคำสั่งที่ไม่มี', '"a".nope()', 'AttributeError', 1, 'สะกด'],
    ['คีย์ที่ไม่มีใน dict', 'd = {}\nprint(d["k"])', 'KeyError', 2, 'k'],
    // ล้มที่บรรทัด 2 ไม่ใช่ 3: ตัวรันป้อน stdin ให้หนึ่งบรรทัดเสมอ input() แรกจึงสำเร็จ
    ['input มากกว่าที่โจทย์ให้', 'x = input()\ny = input()\nz = input()', 'EOFError', 2, 'input()'],
    ['ไลบรารีที่ไม่มี', 'import definitely_not_installed', 'ModuleNotFoundError', 1, 'ไลบรารี'],
];

(async () => {
    for (const [label, code, expectedKind, expectedLine, mustMention] of CASES) {
        const run = await runPythonScript({ code, timeoutMs: 6000, mainFileName: 'solution.py' });
        const explained = explainPythonError(run.error || run.stderr);

        const kindOk = explained.kind === expectedKind;
        const lineOk = explained.line === expectedLine;
        const mentionOk = explained.message.includes(mustMention);
        check(kindOk && lineOk && mentionOk, label,
            `${explained.kind} บรรทัด ${explained.line} · ${explained.message.slice(0, 55)}` +
            (kindOk ? '' : ` [คาด ${expectedKind}]`) +
            (lineOk ? '' : ` [คาดบรรทัด ${expectedLine}]`) +
            (mentionOk ? '' : ` [ต้องมีคำว่า ${mustMention}]`));
    }

    // Nothing wrong means nothing to say.
    const clean = explainPythonError('');
    check(clean.message === '' && clean.line === null, 'ไม่มีข้อผิดพลาดก็ไม่มีข้อความ');

    // An error nobody wrote a rule for still gets a usable sentence, and keeps
    // the raw text for whoever wants it.
    const unknown = explainPythonError('Traceback (most recent call last):\n  File "solution.py", line 4, in <module>\nWeirdError: something odd');
    check(unknown.message.length > 20 && unknown.line === 4 && unknown.raw.includes('WeirdError'),
        'ข้อผิดพลาดที่ไม่รู้จักยังได้ข้อความที่ใช้ได้', `บรรทัด ${unknown.line} · ${unknown.kind}`);

    // No message may leak the temp directory the code ran from, or fall back to
    // pasting the traceback in as the explanation.
    const leaks = [];
    for (const [label, code] of CASES) {
        const run = await runPythonScript({ code, timeoutMs: 6000, mainFileName: 'solution.py' });
        const { message } = explainPythonError(run.error || run.stderr);
        // pysim-run is the temp directory prefix; solution.py and Traceback would
        // mean the raw text leaked through instead of being explained.
        if (/pysim-run|Traceback|solution[.]py/.test(message)) leaks.push(label);
    }
    check(leaks.length === 0, 'ไม่มีข้อความไหนหลุด path ของเครื่องหรือ traceback ดิบ',
        leaks.length ? leaks.join(', ') : `ตรวจ ${CASES.length} กรณี`);

    console.log(`\n${pass} passed, ${fail} failed`);
    process.exitCode = fail ? 1 : 0;
})();
